  "description": "Delegates subagents to Codex: Codex roles Claude can pick (advisor, reviewer, implementer) plus chosen subagent types, in the background or waited on, with independent Codex reviews; measures every run",
  "author": {
    "name": "Bryan Ankielewicz"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "codexAgents": {
      "type": "string",
      "title": "Subagent types sent to Codex",
      "description": "Comma-separated subagent types Codex runs instead of Claude, e.g. general-purpose, code-explorer. * sends every type. Named, isolated and nested calls stay on Claude. Empty: only the duet: roles go to Codex.",
      "default": ""
    },
    "codexSandbox": {
      "type": "string",
      "title": "Codex sandbox",
      "description": "read-only: Codex reads and answers but writes nothing. workspace-write: Codex may also write in the session folder and /tmp. In both, Codex can read any file your account can read. A custom agent whose tools cannot edit always runs read-only.",
      "options": [
        "read-only",
        "workspace-write"
      ],
      "default": "read-only"
    },
    "codexModel": {
      "type": "string",
      "title": "Codex model",
      "description": "Passed to codex as -m. Empty: Codex's own configured model.",
      "default": ""
    },
    "maxConcurrent": {
      "type": "number",
      "title": "Codex runs at once",
      "description": "A routed call beyond this many live Codex runs is refused with a reason.",
      "default": 2
    },
    "timeoutMinutes": {
      "type": "number",
      "title": "Codex timeout (minutes)",
      "description": "A Codex run past this is stopped and the call refused. If duet has to fall back to a one-shot run (streaming couldn't start), that run stops at 10 minutes at most.",
      "default": 20
    },
    "codexConsent": {
      "type": "string",
      "title": "Sending repo content to Codex",
      "description": "ask: once per session before the first handoff. allow: pre-approved (needed for headless claude -p).",
      "options": [
        "ask",
        "allow"
      ],
      "default": "ask"
    },
    "codexRunMode": {
      "type": "string",
      "title": "Wait or background",
      "description": "wait or background for codexAgents types, then overrides by type: advisor=background, Explore=wait. Roles default to advisor wait, reviewer background. A run that can edit always waits.",
      "default": "background"
    },
    "codexFsScope": {
      "type": "string",
      "title": "Codex filesystem scope",
      "description": "anything: Codex's own sandbox, which reads any file your account can read. project: a duet permission profile limits Codex to the session folder (writable only under workspace-write), plus read-only system paths and Codex's own install and memories folders, plus git's own folders in a linked worktree, and hides every other file and, on Linux, /tmp (on macOS, Codex's source makes /tmp readable and writable, even under read-only; not run). On Codex 0.162.1 (Linux), codex exec runs confirmed the hidden files and /tmp; the write limits are partly checked in codex sandbox only (SPEC, Change 0.2.6). Re-check after upgrading Codex.",
      "options": [
        "anything",
        "project"
      ],
      "default": "anything"
    },
    "codexWritePaths": {
      "type": "string",
      "title": "Folders an agent may write",
      "description": "With codexFsScope project and workspace-write: agent=folder;folder entries, comma-separated, e.g. red-test-writer=tests;test. A named agent writes only those project folders and reads the rest; others write the whole project. A folder outside the project or in .git, .codex or .agents (also through a symlink), or not there yet, is ignored and named in the run's result; a malformed value leaves every agent read-only.",
      "default": ""
    },
    "apiCustomUrl": {
      "type": "string",
      "title": "Custom provider base URL",
      "description": "The custom API provider's OpenAI-compatible base URL (https://, or http:// to localhost), e.g. https://my-gateway.example.com/v1 for Azure OpenAI, LiteLLM, LM Studio or a company gateway. Its key is DUET_CUSTOM_API_KEY, entered in /duet provider.",
      "default": ""
    },
    "apiCustomModel": {
      "type": "string",
      "title": "Custom provider default model",
      "description": "The model id runs on the custom provider use (0.4.0). In 0.3.0 the key test lists models instead; test custom <model> names a model directly.",
      "default": ""
    }
  }
}

